/* SM SCHOOL AI v1.9.0 — guided teaching with learner reasoning capture and optional AI analysis. */
let smartTeacherSession=null;
function smartTeacherText(ar,fr,en){return lang==='ar'?ar:lang==='fr'?fr:en}
function smartTeacherPool(subject){
 const learner=typeof activeLearner==='function'?activeLearner():{grade:typeof grade!=='undefined'?grade:''};
 const officialBank=typeof exerciseBankRecords!=='undefined'&&Array.isArray(exerciseBankRecords)?exerciseBankRecords:[];
 const curated=officialBank.filter(x=>x&&x.grade===(learner.grade||grade)&&x.subject===subject&&Array.isArray(x.choices)&&x.choices.length>=2&&Number.isInteger(Number(x.answer_index))&&Number(x.answer_index)>=0&&Number(x.answer_index)<x.choices.length)
  .map(x=>({id:x.id,q:x.question,choices:x.choices,a:Number(x.answer_index),why:x.explanation||'',topic:x.topic||'',lesson:x.lesson||'',difficulty:x.difficulty||'',term:x.term,question_type:x.question_type||'concept'}));
 if(curated.length)return curated;
 const by=typeof subjectPractice!=='undefined'?(subjectPractice[subject]?.[level]||[]):[];
 const generic=typeof demoBank!=='undefined'?(demoBank[level]||[]):[];
 return by.length?by:((/رياضيات|Math|mathemat/i.test(subject))?generic:[]);
}
function smartTeacherAdaptiveProfile(learnerId,subject,rows,errors,now=new Date()){
 const id=String(learnerId||'default'),cutoff=new Date(now.getTime()-30*86400000).toISOString().slice(0,10),today=now.toISOString().slice(0,10);
 const recent=(Array.isArray(rows)?rows:[]).filter(x=>x&&((x.learnerId===id)||(!x.learnerId&&id==='default'))&&x.subject===subject&&String(x.date||'')>=cutoff&&String(x.date||'')<=today);
 let total=0,correct=0;recent.forEach(x=>{const t=Math.max(0,Number(x.total)||0),c=Math.max(0,Math.min(t,Number(x.correct)||0));total+=t;correct+=c});
 const accuracy=total?Math.round(correct/total*100):null;
 const mistakeRows=(Array.isArray(errors)?errors:[]).filter(x=>x&&((x.learnerId===id)||(!x.learnerId&&id==='default'))&&(!x.subject||x.subject===subject));
 const counts={};mistakeRows.slice(-60).forEach(x=>{const label=String(x.topic||x.lesson||'').trim().replace(/\s+/g,' ').slice(0,100);if(label)counts[label]=(counts[label]||0)+1});
 const weakTopics=Object.entries(counts).filter(([,n])=>n>=2).sort((a,b)=>b[1]-a[1]).slice(0,5).map(([topic,count])=>({topic,count}));
 const level=total<5?'discovery':accuracy<50?'support':accuracy<75?'standard':'challenge';
 const note=level==='discovery'?'لا توجد بيانات حديثة كافية؛ سنبدأ بأسئلة استكشافية دون افتراض مستوى التلميذ.':level==='support'?'ستبدأ الحصة بأسئلة تأسيسية، مع إعطاء أولوية للمحاور التي تكررت فيها الأخطاء.':level==='standard'?'سيوازن التدريب بين ترسيخ الأساسيات والأسئلة المتوسطة، مع مراعاة الأخطاء المتكررة.':'سيضم التدريب أسئلة أكثر تحدياً مع مراجعة المحاور التي ظهرت فيها أخطاء.';
 return {learnerId:id,subject,from:cutoff,to:today,total,correct,accuracy,level,weakTopics,note,evidence:total>=20?'strong':total>=5?'limited':'insufficient'};
}
function smartTeacherDifficultyBucket(value){const v=String(value||'').trim().toLowerCase();if(/مبتدئ|سهل|easy|beginner/.test(v))return 'easy';if(/متوسط|medium|intermediate/.test(v))return 'medium';if(/متقدم|صعب|hard|advanced|challenge/.test(v))return 'hard';return 'unknown'}
function smartTeacherSelectAdaptiveQuestions(pool,profile,count=5){
 const unique=[],seen=new Set();(Array.isArray(pool)?pool:[]).forEach(q=>{const key=String(q?.id||q?.q||q?.question||'');if(key&&!seen.has(key)){seen.add(key);unique.push(q)}});
 const limit=Math.max(1,Math.min(Number(count)||5,unique.length));if(!unique.length)return [];
 if(!profile||profile.level==='discovery')return unique.slice(0,limit);
 const weak=(profile.weakTopics||[]).map(x=>String(x.topic||'').toLowerCase()).filter(Boolean);
 const matchesTopic=q=>{const t=`${q.topic||''} ${q.lesson||''}`.toLowerCase();return weak.some(w=>w&&(t.includes(w)||w.includes(t.trim())))};
 const ordered=[...unique].sort((a,b)=>Number(matchesTopic(b))-Number(matchesTopic(a)));
 const buckets={easy:ordered.filter(q=>smartTeacherDifficultyBucket(q.difficulty)==='easy'),medium:ordered.filter(q=>smartTeacherDifficultyBucket(q.difficulty)==='medium'),hard:ordered.filter(q=>smartTeacherDifficultyBucket(q.difficulty)==='hard')};
 if(!buckets.easy.length&&!buckets.medium.length&&!buckets.hard.length)return ordered.slice(0,limit);
 const plans={support:['easy','easy','medium','easy','medium'],standard:['medium','easy','medium','hard','medium'],challenge:['hard','medium','hard','medium','hard']};
 const selected=[],used=new Set();for(const bucket of plans[profile.level]||plans.standard){if(selected.length>=limit)break;const q=(buckets[bucket]||[]).find(x=>!used.has(String(x.id||x.q||x.question||'')));if(q){const key=String(q.id||q.q||q.question||'');used.add(key);selected.push(q)}}
 for(const q of ordered){if(selected.length>=limit)break;const key=String(q.id||q.q||q.question||'');if(!used.has(key)){used.add(key);selected.push(q)}}
 return selected;
}

