 const learner=typeof activeLearner==='function'?activeLearner():{id:'default',name:'التلميذ',grade:typeof grade!=='undefined'?grade:''};
 const options=(typeof subjectsForCurrentGrade==='function'?subjectsForCurrentGrade():[]);
 const dzPdfDocs=(typeof window!=='undefined'&&window.SM_DZLIB&&window.SM_DZLIB._t?window.SM_DZLIB._t.docs():[]);
 const dzPdfOptions=(typeof smLibraryPdfOptions==='function'?smLibraryPdfOptions(learner.grade||grade).map(o=>({value:o.value,title:o.label})):dzPdfDocs.map((d,i)=>({d,i})).filter(x=>x.d.ext==='pdf'&&x.d.grade===(learner.grade||grade)).map(x=>({value:String(x.i),title:x.d.title})));
 const progress=typeof getProgress==='function'?getProgress().filter(x=>x.learnerId===learner.id):[];
 const stats={total:progress.reduce((n,x)=>n+(Number(x.total)||0),0),correct:progress.reduce((n,x)=>n+(Number(x.correct)||0),0)};
 const weak=Object.values(progress.reduce((a,x)=>{const k=x.subject||'';a[k]??={subject:k,c:0,t:0};a[k].c+=Number(x.correct)||0;a[k].t+=Number(x.total)||0;return a},{})).filter(x=>x.t>=5).sort((a,b)=>a.c/a.t-b.c/b.t)[0];
 const chosen=weak?.subject||options[0]||'الرياضيات';
