function startSmartTeacherSession(){
 const subject=document.getElementById('smartTeacherSubject')?.value||'';const pool=smartTeacherPool(subject);
 if(!pool.length){toast(smartTeacherText('لا تتوفر أسئلة معتمدة لهذه المادة والمستوى حالياً. اختر مادة أخرى.','Aucune question disponible pour cette matière et ce niveau. Choisissez une autre matière.','No questions are currently available for this subject and grade. Choose another subject.'));return}
 const learner=activeLearner(),allProgress=typeof getProgress==='function'?getProgress():[];let errors=[];try{const stored=JSON.parse(localStorage.getItem('smSchoolLearningErrors')||'[]');errors=Array.isArray(stored)?stored:[]}catch{}
 const profile=smartTeacherAdaptiveProfile(learner.id,subject,allProgress,errors),selected=smartTeacherSelectAdaptiveQuestions(pool,profile,5);
 smartTeacherSession={subject,learnerId:learner.id,items:selected,startedAt:Date.now(),sessionId:'st-'+Date.now().toString(36),difficulty:profile.level,adaptiveProfile:profile,currentIndex:0,answers:{},profile};
 const mount=document.getElementById('smartTeacherMount');if(!mount)return;
 const lesson=(typeof starterLessons!=='undefined'?starterLessons:[]).find(x=>x.s===subject&&x.g===level&&x.gr===grade)||(typeof starterLessons!=='undefined'?starterLessons:[]).find(x=>x.s===subject&&x.g===level&&!x.gr);
 const intro=lesson?`<h3>${escapeReviewText(lesson.title?.[lang]||lesson.title?.ar||'')}</h3><p><b>${smartTeacherText('هدف التعلم:','Objectif :','Learning goal:')}</b> ${escapeReviewText(lesson.goal?.[lang]||lesson.goal?.ar||'')}</p><div class="notice">${escapeReviewText(lesson.body?.[lang]||lesson.body?.ar||'')}</div>`:`<div class="notice">${smartTeacherText('لا توجد بطاقة شرح جاهزة لهذه المادة في المستوى الحالي. سنبدأ بأسئلة التدريب المتاحة دون تقديم درس غير موثق.','Aucune fiche de cours prête pour cette matière et ce niveau. Nous commencerons par les questions disponibles.','No ready-made lesson card is available for this subject and grade. We will begin with available practice questions without presenting an unverified lesson.')}</div>`;
 smartTeacherSession.lessonIntro=intro;
 smartTeacherRenderStep();
 mount.scrollIntoView?.({behavior:'smooth',block:'start'});
}
function smartTeacherCaptureStep(){
 const s=smartTeacherSession;if(!s)return;const i=s.currentIndex||0,selected=document.querySelector(`input[name="smartTeacherQ${i}"]:checked`),reasoning=document.getElementById(`smartTeacherReasoning${i}`)?.value||'';
 if(selected)s.answers[i]={...(s.answers[i]||{}),choice:Number(selected.value),reasoning:String(reasoning).trim().slice(0,1200)};
 else if(reasoning.trim())s.answers[i]={...(s.answers[i]||{}),choice:null,reasoning:String(reasoning).trim().slice(0,1200)};
}
function smartTeacherRenderStep(){
 const s=smartTeacherSession,mount=document.getElementById('smartTeacherMount');if(!s||!mount||!s.items.length)return;const i=s.currentIndex||0,q=s.items[i],saved=s.answers[i]||{},last=i===s.items.length-1;
 mount.innerHTML=`<section class="panel smart-teacher-session">${i===0&&s.lessonIntro?`<div class="smart-teacher-lesson-intro"><span class="pill">${smartTeacherText('مرحلة الشرح','Étape explication','Explain')}</span>${s.lessonIntro}<p class="notice">${escapeReviewText(s.profile?.note||'')}</p></div>`:''}<div class="smart-teacher-step-head"><span class="pill">${smartTeacherText('السؤال','Question','Question')} ${i+1} ${smartTeacherText('من','sur','of')} ${s.items.length}</span><span class="step-progress-label">${Math.round((i+1)/s.items.length*100)}%</span></div><div class="step-progress" role="progressbar" aria-valuemin="0" aria-valuemax="${s.items.length}" aria-valuenow="${i+1}"><span style="width:${(i+1)/s.items.length*100}%"></span></div><article class="question-card"><h3>${i+1}. ${escapeReviewText(q.q||q.question||'')}</h3><div class="answer-options">${(q.choices||[]).map((c,j)=>`<label><input type="radio" name="smartTeacherQ${i}" value="${j}" ${saved.choice===j?'checked':''}> ${escapeReviewText(c)}</label>`).join('')}</div><label class="reasoning-label" for="smartTeacherReasoning${i}">${smartTeacherText('فكّر بهدوء: كيف وصلت إلى إجابتك؟ (اختياري)','Réfléchissez : comment avez-vous trouvé ? (facultatif)','Think it through: how did you reach your answer? (optional)')}</label><textarea id="smartTeacherReasoning${i}" rows="3" maxlength="1200" placeholder="${smartTeacherText('اكتب خطوات تفكيرك باختصار…','Décrivez brièvement votre raisonnement…','Briefly describe your reasoning…')}">${escapeReviewText(saved.reasoning||'')}</textarea></article>${saved.feedback?`<div class="smart-teacher-feedback ${saved.checkedCorrect?'is-correct':'is-hint'}" role="status"><b>${saved.checkedCorrect?smartTeacherText('أحسنت!','Bravo !','Well done!'):smartTeacherText('تلميح للتفكير','Indice de réflexion','Thinking hint')}</b><p>${escapeReviewText(saved.feedback)}</p></div>`:''}<div class="smart-teacher-step-actions"><button class="secondary-btn" type="button" onclick="smartTeacherCheckCurrentAnswer()">${smartTeacherText('تحقق من إجابتي','Vérifier ma réponse','Check my answer')}</button>${i>0?`<button class="secondary-btn" type="button" onclick="smartTeacherStep(-1)">→ ${smartTeacherText('السابق','Précédent','Previous')}</button>`:''}${last?`<button class="primary-btn" type="button" onclick="submitSmartTeacherSession()">${smartTeacherText('إنهاء الحصة وتصحيح الإجابات','Terminer et corriger','Finish and check answers')}</button>`:`<button class="primary-btn" type="button" onclick="smartTeacherStep(1)">${smartTeacherText('السؤال التالي','Question suivante','Next question')} ←</button>`}</div><div id="smartTeacherResult" aria-live="polite"></div></section>`;
}
function smartTeacherCheckCurrentAnswer(){
 const s=smartTeacherSession;if(!s||s.submitted)return false;smartTeacherCaptureStep();const i=s.currentIndex||0,q=s.items[i],saved=s.answers[i]||{};
 if(saved.choice===null||saved.choice===undefined){saved.feedback=smartTeacherText('اختر إجابة أولاً، ثم حاول شرح سبب اختيارك.','Choisissez d’abord une réponse et expliquez votre choix.','Choose an answer first, then explain why you chose it.');saved.checkedCorrect=false;s.answers[i]=saved;smartTeacherRenderStep();return false;}
 const ok=Number(saved.choice)===Number(q.a);saved.checkedCorrect=ok;saved.attempts=(Number(saved.attempts)||0)+1;
 saved.feedback=ok?(q.why||smartTeacherText('إجابة صحيحة. حاول الآن توضيح القاعدة التي اعتمدت عليها.','Bonne réponse. Expliquez maintenant la règle utilisée.','Correct. Now explain the rule you used.')):(q.hint||smartTeacherText('لا تتعجل. أعد قراءة السؤال وحدد المعطيات المهمة، ثم استبعد الاختيار الذي لا ينسجم معها وحاول مرة أخرى.','Prenez votre temps. Relisez la question, repérez les données importantes et éliminez le choix qui ne leur correspond pas.','Take your time. Reread the question, identify the key information, eliminate the option that does not fit, and try again.'));
 s.answers[i]=saved;smartTeacherRenderStep();return ok;
}
function smartTeacherStep(delta){const s=smartTeacherSession;if(!s||s.submitted)return;smartTeacherCaptureStep();s.currentIndex=Math.max(0,Math.min(s.items.length-1,(s.currentIndex||0)+Number(delta||0)));smartTeacherRenderStep();}
function submitSmartTeacherSession(){
 const s=smartTeacherSession;if(!s||s.submitted)return;smartTeacherCaptureStep();let correct=0,answered=0;
 const reasoningRecords=[],reviewCards=[];
 s.items.forEach((q,i)=>{const saved=s.answers[i]||{},choice=saved.choice,reasoning=saved.reasoning||'';if(choice!==null&&choice!==undefined){answered++;const ok=Number(choice)===Number(q.a);if(ok)correct++;reviewCards.push(`<article class="answer-review-card"><b>${i+1}. ${ok?smartTeacherText('إجابة صحيحة ✓','Bonne réponse ✓','Correct ✓'):smartTeacherText('لنراجع الإجابة','Revoir la réponse','Review this answer')}</b><p>${escapeReviewText(q.q||q.question||'')}</p><p>${smartTeacherText('إجابتك:','Votre réponse :','Your answer:')} ${escapeReviewText(q.choices?.[Number(choice)]||'')}</p><p>${smartTeacherText('الإجابة الصحيحة:','Bonne réponse :','Correct answer:')} ${escapeReviewText(q.choices?.[q.a]||'')}</p>${q.why?`<p>${escapeReviewText(q.why)}</p>`:''}</article>`);reasoningRecords.push({learnerId:s.learnerId,sessionId:s.sessionId,subject:s.subject,question:String(q.q||q.question||''),studentAnswer:String(q.choices?.[Number(choice)]||''),correctAnswer:String(q.choices?.[q.a]||''),isCorrect:ok,reasoning,explanation:String(q.why||''),recordedAt:new Date().toISOString()});}else{reviewCards.push(`<article class="answer-review-card"><b>${i+1}. ${smartTeacherText('سؤال دون إجابة','Question sans réponse','Unanswered question')}</b><p>${escapeReviewText(q.q||q.question||'')}</p><p>${smartTeacherText('الإجابة الصحيحة:','Bonne réponse :','Correct answer:')} ${escapeReviewText(q.choices?.[q.a]||'')}</p>${q.why?`<p>${escapeReviewText(q.why)}</p>`:''}</article>`);}});
 if(!answered){toast(smartTeacherText('أجب عن سؤال واحد على الأقل قبل التصحيح.','Répondez à au moins une question.','Answer at least one question before grading.'));return}
 s.submitted=true;const learner=activeLearner();const record={date:new Date().toISOString().slice(0,10),grade:learner.grade||grade,subject:s.subject,mode:'smart-teacher',correct,total:s.items.length,learnerId:learner.id,learnerName:learner.name,at:Date.now(),answered};const rows=getProgress();rows.push(record);saveProgress(rows);
 try{if(typeof learningMemorySnapshot==='function')learningMemorySnapshot(learner.id)}catch{}
 try{const prior=JSON.parse(localStorage.getItem('smSchoolReasoningRecords')||'[]');const safe=Array.isArray(prior)?prior:[];safe.push(...reasoningRecords);localStorage.setItem('smSchoolReasoningRecords',JSON.stringify(safe.slice(-500)));}catch{}
 const pct=Math.round(correct/s.items.length*100),next=pct<50?smartTeacherText('أعد قراءة الشرح ثم تدرب على أسئلة أسهل.','Relisez la leçon puis entraînez-vous avec des questions plus simples.','Review the explanation, then practise with easier questions.'):pct<80?smartTeacherText('أحسنت. راجع الأخطاء وأعد التدريب.','Bien joué. Revoyez les erreurs et recommencez.','Good work. Review mistakes and practise again.'):smartTeacherText('إتقان جيد. انتقل إلى مستوى أكثر تحدياً عند توفر محتوى مناسب.','Bonne maîtrise. Passez à un niveau plus difficile si le contenu est disponible.','Good mastery. Move to a more challenging level when suitable content is available.');
 const diagnosis=smartTeacherBuildSessionDiagnosis(s);
 try{const prior=JSON.parse(localStorage.getItem('smSchoolLearningErrors')||'[]'),safe=Array.isArray(prior)?prior:[];safe.push(...diagnosis.errors);localStorage.setItem('smSchoolLearningErrors',JSON.stringify(safe.slice(-500)));}catch{}
 const result=document.getElementById('smartTeacherResult');if(result)result.innerHTML=`<div class="test-result"><h3>${smartTeacherText('نتيجة الحصة','Résultat de la séance','Session result')}: ${correct}/${s.items.length} (${pct}%)</h3><p>${next}</p>${diagnosis.html}<small>${smartTeacherText('تم حفظ النتيجة وخطوات التفكير المكتوبة محلياً في ملف هذا التلميذ.','Le résultat et le raisonnement écrit sont enregistrés localement pour cet élève.','The result and written reasoning were saved locally to this learner’s profile.')}</small><button class="secondary-btn" onclick="analyzeSmartTeacherReasoning()">${smartTeacherText('حلّل طريقة تفكيري بالذكاء الاصطناعي','Analyser mon raisonnement avec l’IA','Analyze my reasoning with AI')}</button><div class="smart-teacher-review-list">${reviewCards.join('')}</div><div id="smartTeacherReasoningAnalysis" aria-live="polite"></div><button class="secondary-btn" onclick="startSmartTeacherSession()">${smartTeacherText('حصة تدريب جديدة','Nouvelle séance','Start another session')}</button></div>`;
}
function smartTeacherBuildSessionDiagnosis(session){
 const groups=new Map(),errors=[];
 (session.items||[]).forEach((q,i)=>{const saved=session.answers?.[i]||{},answered=saved.choice!==null&&saved.choice!==undefined,correct=answered&&Number(saved.choice)===Number(q.a);const topic=String(q.topic||q.lesson||'').trim();if(!topic)return;const g=groups.get(topic)||{topic,total:0,correct:0,incorrect:0,unanswered:0,questions:[]};g.total++;if(correct)g.correct++;else if(answered){g.incorrect++;errors.push({learnerId:session.learnerId,sessionId:session.sessionId,subject:session.subject,topic,question:String(q.q||q.question||''),studentAnswer:String(q.choices?.[Number(saved.choice)]||''),correctAnswer:String(q.choices?.[q.a]||''),recordedAt:new Date().toISOString()});}else g.unanswered++;g.questions.push(q);groups.set(topic,g);});
 const weak=[...groups.values()].filter(g=>g.incorrect+g.unanswered>0).sort((a,b)=>(b.incorrect+b.unanswered)-(a.incorrect+a.unanswered));
 if(!weak.length)return {errors,html:`<section class="smart-teacher-diagnosis"><h4>${smartTeacherText('خريطة الفهم','Carte de compréhension','Understanding map')}</h4><p>${smartTeacherText('لم تظهر أخطاء في المحاور المصنفة لهذه الحصة. هذه نتيجة تدريبية وليست تشخيصاً نهائياً.','Aucune erreur dans les thèmes classés de cette séance. Ceci reste un résultat formatif.','No errors appeared in the tagged topics in this session. This is formative evidence, not a definitive diagnosis.')}</p></section>`};
 const rows=weak.map(g=>{const count=g.incorrect+g.unanswered,available=smartTeacherPool(session.subject).some(q=>String(q.topic||q.lesson||'').trim()===g.topic);return `<article class="smart-teacher-diagnosis-topic"><div><b>${escapeReviewText(g.topic)}</b><small>${g.incorrect} ${smartTeacherText('إجابة خاطئة','réponses incorrectes','incorrect')} · ${g.unanswered} ${smartTeacherText('دون إجابة','sans réponse','unanswered')} · ${g.correct}/${g.total} ${smartTeacherText('صحيحة','correctes','correct')}</small></div>${available?`<button class="secondary-btn" type="button" onclick="smartTeacherStartRemedialTopic(decodeURIComponent('${encodeURIComponent(g.topic)}'))">${smartTeacherText('تدرب على هذا المحور','Réviser ce thème','Practise this topic')}</button>`:''}</article>`}).join('');
 return {errors,html:`<section class="smart-teacher-diagnosis"><h4>🧭 ${smartTeacherText('خريطة الفهم وخطة العلاج','Carte de compréhension et plan de soutien','Understanding map and support plan')}</h4><p>${smartTeacherText('هذه ملاحظات مبنية على إجابات هذه الحصة فقط؛ لا تكفي وحدها للحكم على مستوى التلميذ.','Ces observations reposent uniquement sur cette séance et ne suffisent pas à évaluer définitivement l’élève.','These observations are based on this session only and are not enough to make a definitive judgment about the learner.')}</p>${rows}</section>`};
}
function smartTeacherStartRemedialTopic(topic){
 const s=smartTeacherSession;if(!s)return false;const pool=smartTeacherPool(s.subject),matches=pool.filter(q=>String(q.topic||q.lesson||'').trim()===String(topic||'').trim());if(!matches.length){toast(smartTeacherText('لا تتوفر أسئلة إضافية موثقة لهذا المحور حالياً.','Aucune autre question vérifiée disponible pour ce thème.','No additional verified questions are available for this topic.'));return false;}
 const learner=activeLearner();smartTeacherSession={subject:s.subject,learnerId:s.learnerId,items:matches.slice(0,3),startedAt:Date.now(),sessionId:'st-remedial-'+Date.now().toString(36),difficulty:'support',adaptiveProfile:s.adaptiveProfile,currentIndex:0,answers:{},profile:{...s.profile,note:smartTeacherText('تدريب علاجي قصير على محور ظهر فيه تعثر.','Courte révision ciblée sur un thème difficile.','A short targeted practice on a topic that needs support.')}};smartTeacherRenderStep();document.getElementById('smartTeacherMount')?.scrollIntoView?.({behavior:'smooth',block:'start'});return true;
}


async function analyzeSmartTeacherReasoning(){
 const s=smartTeacherSession,mount=document.getElementById('smartTeacherReasoningAnalysis');if(!s||!mount)return;
 let records=[];try{records=JSON.parse(localStorage.getItem('smSchoolReasoningRecords')||'[]')}catch{}
 const relevant=(Array.isArray(records)?records:[]).filter(x=>x.learnerId===s.learnerId&&x.subject===s.subject&&x.sessionId===s.sessionId);
 const withReasoning=relevant.filter(x=>x.reasoning);
 if(!withReasoning.length){mount.innerHTML=`<p class="notice">${smartTeacherText('لم تُكتب خطوات تفكير بعد. اكتبها في خانة كل سؤال ثم أعد الحصة.','Aucun raisonnement écrit. Ajoutez vos étapes dans les champs des questions.','No written reasoning was provided. Add reasoning in the question fields during a session.')}</p>`;return}
 const learner=activeLearner();const context=withReasoning.map((x,i)=>`${i+1}. Question: ${x.question}\nStudent answer: ${x.studentAnswer}\nCorrect answer: ${x.correctAnswer}\nStudent reasoning: ${x.reasoning}\nCorrect: ${x.isCorrect}\nVerified explanation: ${x.explanation}`).join('\n\n').slice(0,5000);
 mount.innerHTML=`<p class="notice">${smartTeacherText('جارٍ إرسال خطوات التفكير التي اخترت تحليلها إلى المعلّم الذكي…','Envoi du raisonnement au tuteur IA…','Sending the reasoning you chose to the AI tutor…')}</p>`;
 try{const response=await fetch(`${apiBase()}/api/v1/ai/tutor`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({task:'evaluate',message:smartTeacherText('حلّل طريقة تفكير التلميذ لا النتيجة فقط. حدّد الخطوة الصحيحة، وأي تصور خاطئ أو فجوة مفاهيمية، واشرح كيف يصحح تفكيره. لا تخترع معلومات غير موجودة.\n','Analysez le raisonnement, pas seulement le résultat. Identifiez les étapes correctes, les idées fausses et comment progresser.\n','Analyze the learner’s reasoning, not only the result. Identify sound steps, misconceptions and how to improve.\n')+context,student_answer:context,language:lang,grade:learner.grade||grade,subject:s.subject,learner_name:learner.name,learning_context:'Optional, user-initiated reasoning analysis. Give formative feedback, distinguish evidence from inference, and do not assign an official grade.'})});const data=await response.json();if(!response.ok)throw new Error(typeof data.detail==='string'?data.detail:JSON.stringify(data.detail));
 const isAi=data.mode!=='demo';mount.innerHTML=`<div class="answer-review-card"><b>${isAi?smartTeacherText('تحليل المعلّم الذكي','Analyse du tuteur IA','AI tutor analysis'):smartTeacherText('وضع تجريبي — لم يُنفذ تحليل ذكاء اصطناعي','Mode démo — aucune analyse IA effectuée','Demo mode — no AI analysis was performed')}</b><p style="white-space:pre-wrap">${escapeReviewText(data.answer||'')}</p>${!isAi?`<small>${smartTeacherText('أدخل مفتاح Groq داخل التطبيق للحصول على تحليل فعلي.','Saisissez une clé Groq dans l’application pour une analyse réelle.','Enter a Groq key in the app for an actual analysis.')}</small>`:''}</div>`;
 }catch(error){mount.innerHTML=`<p class="notice">${smartTeacherText('تعذر تحليل التفكير حالياً. بقيت الإجابات محفوظة محلياً.','Analyse indisponible. Les réponses restent enregistrées localement.','Analysis is unavailable. Your responses remain saved locally.')}: ${escapeReviewText(error.message)}</p>`}
}


